import type { VisualizerView } from "../../shared/api/generated/media-wire";

// Generated by media-render's visualizer_contact_sheet example. These are real off-screen frames
// from the same VisualizerRenderer and shaders used by program output, not browser approximations.
const previewModules = import.meta.glob<string>("./previews/*.png", {
	eager: true,
	query: "?url",
	import: "default",
});

const previewsByTypeId = new Map<number, string>();
for (const [path, url] of Object.entries(previewModules)) {
	const match = /\/(\d{3})-[^/]+\.png$/u.exec(path);
	if (match) previewsByTypeId.set(Number(match[1]), url);
}

