/** A representative frame rendered by the actual built-in visualizer implementation. */
export function visualizerPreviewUrl(
	visualizer: Pick<VisualizerView, "typeId">,
): string {
	return previewsByTypeId.get(visualizer.typeId) ?? "";
}

export function hasRenderedVisualizerPreview(typeId: number): boolean {
	return previewsByTypeId.has(typeId);
}
